#include "GBuffer.h"
#include <stdexcept>
GBuffer::GBuffer(int W,int H):w(W),h(H){glGenFramebuffers(1,&fbo);glBindFramebuffer(GL_FRAMEBUFFER,fbo);auto tex=[&](GLuint&t,GLenum internal,GLenum format){glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexImage2D(GL_TEXTURE_2D,0,internal,w,h,0,format,GL_FLOAT,nullptr);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);};tex(position,GL_RGB16F,GL_RGB);tex(normal,GL_RGB16F,GL_RGB);tex(albedo,GL_RGBA16F,GL_RGBA);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,position,0);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT1,GL_TEXTURE_2D,normal,0);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT2,GL_TEXTURE_2D,albedo,0);GLenum a[3]={GL_COLOR_ATTACHMENT0,GL_COLOR_ATTACHMENT1,GL_COLOR_ATTACHMENT2};glDrawBuffers(3,a);glGenRenderbuffers(1,&depth);glBindRenderbuffer(GL_RENDERBUFFER,depth);glRenderbufferStorage(GL_RENDERBUFFER,GL_DEPTH_COMPONENT24,w,h);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,depth);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)throw std::runtime_error("GBuffer incomplete");glBindFramebuffer(GL_FRAMEBUFFER,0);}
GBuffer::~GBuffer(){glDeleteTextures(1,&position);glDeleteTextures(1,&normal);glDeleteTextures(1,&albedo);glDeleteRenderbuffers(1,&depth);glDeleteFramebuffers(1,&fbo);}void GBuffer::bind()const{glBindFramebuffer(GL_FRAMEBUFFER,fbo);}

